attributes.cssVariables:
:root {
  --font-sans: 'DM Sans', ui-sans-serif, system-ui, sans-serif;
  --font-serif: 'Source Serif 4', ui-serif, Georgia, serif;
  --font-mono: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  --background: #f2efe8;
  --card: #fffdf8;
  --foreground: #111216;
  --card-foreground: #111216;
  --muted: #e5e0d6;
  --muted-foreground: #66645f;
  --border: #ccc6ba;
  --input: #ccc6ba;
  --primary: #ff4b2b;
  --primary-foreground: #190704;
  --accent: #ff4b2b;
  --accent-foreground: #190704;
  --ring: #ff4b2b;
  --radius: 0.125rem;
  --cutroom-ink: #111216;
  --cutroom-paper: #f2efe8;
  --cutroom-panel: #1b1d23;
  --cutroom-panel-soft: #292c34;
  --cutroom-screen: #d5d7d2;
  --cutroom-signal: #ff4b2b;
  --cutroom-rule-dark: #3d4049;
}
